CREATE TABLE telegram_access(user_id INTEGER PRIMARY KEY CHECK(user_id>0),role TEXT NOT NULL CHECK(role IN ('OWNER','USER')),enabled INTEGER NOT NULL DEFAULT 1,granted_by INTEGER,created_at TEXT NOT NULL);
CREATE TABLE telegram_subscriptions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES telegram_access(user_id),filter_json TEXT NOT NULL,model_version TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','needs_update','deleted')),reason TEXT,created_at TEXT NOT NULL);
CREATE INDEX telegram_subscriptions_user ON telegram_subscriptions(user_id,status);
CREATE TABLE telegram_class_mappings(old_id INTEGER NOT NULL REFERENCES classes(class_id),model_version TEXT NOT NULL,new_id INTEGER NOT NULL REFERENCES classes(class_id),confirmed_by INTEGER NOT NULL REFERENCES telegram_access(user_id),confirmed_at TEXT NOT NULL,PRIMARY KEY(old_id,model_version));
CREATE TABLE telegram_seen(text_sha256 TEXT PRIMARY KEY,content_id INTEGER NOT NULL REFERENCES contents(id),result_set_id TEXT REFERENCES result_sets(result_set_id),seen_at TEXT NOT NULL);
CREATE INDEX telegram_seen_content ON telegram_seen(content_id);
CREATE TABLE telegram_outbox(event_id TEXT PRIMARY KEY,text_sha256 TEXT NOT NULL UNIQUE,content_id INTEGER NOT NULL REFERENCES contents(id),result_set_id TEXT NOT NULL REFERENCES result_sets(result_set_id),payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE telegram_deliveries(event_id TEXT NOT NULL REFERENCES telegram_outbox(event_id),user_id INTEGER NOT NULL REFERENCES telegram_access(user_id),state TEXT NOT NULL CHECK(state IN ('queued','running','sent','failed','cancelled')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL,owner TEXT,error TEXT,message_id INTEGER,sent_at TEXT,PRIMARY KEY(event_id,user_id));
CREATE TABLE telegram_delivery_subscriptions(event_id TEXT NOT NULL,user_id INTEGER NOT NULL,subscription_id TEXT NOT NULL REFERENCES telegram_subscriptions(id),PRIMARY KEY(event_id,user_id,subscription_id),FOREIGN KEY(event_id,user_id) REFERENCES telegram_deliveries(event_id,user_id));
CREATE TABLE telegram_attempts(event_id TEXT NOT NULL,user_id INTEGER NOT NULL,attempt INTEGER NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,outcome TEXT,error TEXT,message_id INTEGER,PRIMARY KEY(event_id,user_id,attempt),FOREIGN KEY(event_id,user_id) REFERENCES telegram_deliveries(event_id,user_id));
CREATE TABLE telegram_legacy_imports(path TEXT PRIMARY KEY,sha256 TEXT NOT NULL,imported_at TEXT NOT NULL);
CREATE TABLE telegram_search_sessions(user_id INTEGER PRIMARY KEY REFERENCES telegram_access(user_id),filter_json TEXT NOT NULL,cursor TEXT);
